-- ════════════════════════════════════════════════════════════════════════
--  CrowdWisdomTrading pipeline — SQLite schema
--  Timestamps are stored as ISO-8601 TEXT (UTC unless suffixed _et), which
--  sorts chronologically as text. All stage writers are idempotent (they
--  DELETE then re-insert), so the explicit schema & indexes below are kept.
-- ════════════════════════════════════════════════════════════════════════
PRAGMA foreign_keys = ON;

-- ── Trades (generated by backtesting the parameter grid) ────────────────
CREATE TABLE IF NOT EXISTS trades (
    trade_id       TEXT PRIMARY KEY,
    permutation_id TEXT NOT NULL,
    family         TEXT NOT NULL,
    symbol         TEXT NOT NULL,
    side           TEXT NOT NULL,
    entry_time     TEXT NOT NULL,   -- ISO-8601 UTC
    exit_time      TEXT NOT NULL,   -- ISO-8601 UTC
    entry_px       REAL,
    exit_px        REAL,
    qty            REAL,
    pnl            REAL,
    pnl_pct        REAL,
    bars_held      INTEGER,
    exit_reason    TEXT,
    params_json    TEXT
);
CREATE INDEX IF NOT EXISTS idx_trades_perm  ON trades(permutation_id);
CREATE INDEX IF NOT EXISTS idx_trades_entry ON trades(entry_time);
CREATE INDEX IF NOT EXISTS idx_trades_exit  ON trades(exit_time);

-- ── Macro events (scraped via Apify) ────────────────────────────────────
CREATE TABLE IF NOT EXISTS macro_events (
    event_id        TEXT PRIMARY KEY,
    ts_utc          TEXT NOT NULL,      -- ISO-8601 UTC
    event_time_est  TEXT NOT NULL,      -- ISO-8601 America/New_York (DST-aware)
    ts_et           TEXT NOT NULL,      -- Backwards-compatibility alias for event_time_est
    event_name      TEXT NOT NULL,
    event_type      TEXT,               -- CPI / FOMC / NFP / UNEMP / JOBLESS / OTHER
    actual          REAL,
    forecast        REAL,
    previous        REAL,
    surprise        REAL,               -- actual - forecast (where available)
    impact          TEXT,
    country         TEXT,
    source          TEXT,
    raw_ref         TEXT
);
CREATE INDEX IF NOT EXISTS idx_events_ts   ON macro_events(ts_utc);
CREATE INDEX IF NOT EXISTS idx_events_est  ON macro_events(event_time_est);
CREATE INDEX IF NOT EXISTS idx_events_type ON macro_events(event_type);

-- ── News (scraped via Tavily / Exa) ─────────────────────────────────────
CREATE TABLE IF NOT EXISTS news (
    news_id             TEXT PRIMARY KEY,
    published_utc       TEXT,             -- ISO-8601 UTC
    source              TEXT,             -- tavily / exa
    headline            TEXT,
    url                 TEXT,
    snippet             TEXT,
    sentiment           REAL,             -- Primary sentiment score in [-1, 1]
    sentiment_vader     REAL,             -- General VADER compound in [-1, 1]
    sentiment_financial REAL              -- Loughran-McDonald / FinBERT financial in [-1, 1]
);
CREATE INDEX IF NOT EXISTS idx_news_pub ON news(published_utc);

-- ── Features: one row per (permutation, period). Labels (y_*) are stored
--    here for convenience but are NEVER fed back in as features. ──────────
CREATE TABLE IF NOT EXISTS features (
    permutation_id TEXT NOT NULL,
    period_start   TEXT NOT NULL,   -- ISO-8601 UTC, start of the prediction period
    family         TEXT,
    feature_json   TEXT,            -- all feature columns as JSON (schema-flexible)
    y_pnl          REAL,            -- label: realised pnl over this period
    y_winrate      REAL,            -- label: realised win rate over this period
    n_trades       INTEGER,
    PRIMARY KEY (permutation_id, period_start)
);
CREATE INDEX IF NOT EXISTS idx_features_period ON features(period_start);

-- ── Predictions (one row per run/period/permutation/model) ──────────────
CREATE TABLE IF NOT EXISTS predictions (
    run_id         TEXT NOT NULL,
    period_start   TEXT NOT NULL,
    permutation_id TEXT NOT NULL,
    model          TEXT NOT NULL,
    y_pred         REAL,
    rank           INTEGER,
    selected       INTEGER,         -- 0 / 1
    y_true         REAL,
    PRIMARY KEY (run_id, period_start, permutation_id, model)
);
CREATE INDEX IF NOT EXISTS idx_pred_period ON predictions(period_start);

-- ── Backtest results: per-period realised performance per strategy ──────
CREATE TABLE IF NOT EXISTS backtest_results (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id        TEXT NOT NULL,
    strategy      TEXT NOT NULL,    -- model name or baseline name
    period_start  TEXT,             -- ISO-8601 UTC
    realized_pnl  REAL,
    realized_ret  REAL,
    n_trades      INTEGER
);
CREATE INDEX IF NOT EXISTS idx_bt_run ON backtest_results(run_id, strategy);

-- ── Run-level summary metrics (Sharpe / Sortino / MaxDD / ...) ──────────
CREATE TABLE IF NOT EXISTS run_metrics (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    run_id       TEXT NOT NULL,
    strategy     TEXT NOT NULL,
    metric_name  TEXT NOT NULL,
    metric_value REAL
);
CREATE INDEX IF NOT EXISTS idx_runmetrics ON run_metrics(run_id, strategy);
